import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";

const STEPS = [
  "Приёмка и диагностика",
  "Согласование цены",
  "Ремонт в работе",
  "Готово, можно забирать",
];

const MESSAGES = [
  { text: "Приняли машину, загнали на подъёмник №3", img: false },
  { text: "Диагностика: люфт в правой шаровой. Цена 4 200 ₽, согласовано", img: false },
  { text: "Заменили шаровую, фото работ", img: true },
  { text: "Сход-развал выставлен. Забирайте, ключи на ресепшене", img: false },
];

export default function MasterChat() {
  const reduce = useReducedMotion();
  const [step, setStep] = useState(0);

  useEffect(() => {
    if (reduce) return;
    const t = setInterval(() => {
      setStep((s) => (s + 1) % (MESSAGES.length + 1));
    }, 2600);
    return () => clearInterval(t);
  }, [reduce]);

  const visible = reduce ? MESSAGES.length : Math.min(step, MESSAGES.length);
  const typing = !reduce && step < MESSAGES.length;

  return (
    <section className="w-full border-t border-line bg-background">
      <div className="mx-auto max-w-6xl px-5 py-16 sm:py-20">
        <div className="grid gap-10 lg:grid-cols-[1fr_1.1fr] lg:items-center">
          <div>
            <p className="text-sm font-medium uppercase tracking-wider text-accent-text">
              Без звонков
            </p>
            <h2 className="mt-3 text-3xl font-semibold leading-tight text-foreground sm:text-4xl">
              Ремонт виден по этапам, пока вы на работе
            </h2>
            <p className="mt-4 max-w-md text-base leading-relaxed text-muted-foreground">
              Мастер пишет в Telegram: что нашёл, сколько стоит, что уже сделал.
              Фото работ приходят в тот же чат. 4 этапа — от приёмки до выдачи ключей.
            </p>

            <div className="mt-8 space-y-3">
              {STEPS.map((label, i) => {
                const done = i < visible;
                const current = i === visible && !typing;
                return (
                  <div key={label} className="flex items-center gap-3">
                    <span
                      className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border text-xs font-medium ${
                        done
                          ? "border-primary bg-primary text-primary-foreground"
                          : current
                            ? "border-primary text-primary"
                            : "border-line text-muted-foreground"
                      }`}
                    >
                      {done ? "✓" : i + 1}
                    </span>
                    <span
                      className={`text-sm ${
                        done || current ? "text-foreground" : "text-muted-foreground"
                      }`}
                    >
                      {label}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="rounded-2xl border border-line bg-surface-alt p-4 sm:p-5">
            <div className="flex items-center gap-3 border-b border-line pb-3">
              <div className="flex h-9 w-9 items-center justify-center rounded-full bg-primary text-sm font-semibold text-primary-foreground">
                Г24
              </div>
              <div>
                <p className="text-sm font-medium text-foreground">Мастер, подъёмник №3</p>
                <p className="text-xs text-muted-foreground">Гараж 24 · Telegram</p>
              </div>
              <span className="ml-auto text-xs text-muted-foreground">сейчас</span>
            </div>

            <div className="flex min-h-[280px] flex-col justify-end gap-2 pt-4">
              {MESSAGES.slice(0, visible).map((m, i) => (
                <motion.div
                  key={i}
                  initial={reduce ? false : { opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.35 }}
                  className="max-w-[85%] self-start rounded-2xl rounded-bl-sm border border-line bg-background px-3 py-2"
                >
                  <p className="text-sm leading-snug text-foreground">{m.text}</p>
                  {m.img && (
