import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";

const messages = [
  { author: "Мастер Артём", time: "9:12", text: "Авто на подъёмнике №3. Начинаю с ходовой." },
  { author: "Мастер Артём", time: "10:40", text: "Фото: передние амортизаторы, подтёки масла. Меняю оба.", photo: true },
  { author: "Мастер Артём", time: "13:05", text: "Запчасти установлены. Фото прикрепил." },
  { author: "Мастер Артём", time: "15:20", text: "Готово. Съём с подъёмника, тестовый проезд." },
];

const stages = [
  "Диагностика",
  "Согласование цены",
  "Ремонт",
  "Контрольный проезд",
  "Выдача авто",
];

export default function MasterChat() {
  const reduced = useReducedMotion();
  const [step, setStep] = useState(reduced ? messages.length : 1);

  useEffect(() => {
    if (reduced) return;
    const id = setInterval(() => {
      setStep((s) => (s >= messages.length ? s : s + 1));
    }, 2200);
    return () => clearInterval(id);
  }, [reduced]);

  const visible = messages.slice(0, step);
  const activeStage = Math.min(step * 1, stages.length - 1);

  return (
    <section className="bg-background py-16 md:py-24">
      <div className="mx-auto max-w-6xl px-4">
        <div className="mb-10 flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
          <h2 className="max-w-xl text-2xl font-semibold tracking-tight text-foreground md:text-4xl">
            Как выглядит ремонт в переписке
          </h2>
          <p className="max-w-sm text-sm leading-relaxed text-muted-foreground md:text-base">
            Средний ремонт занимает один день. За это время в Telegram приходят
            4–6 сообщений с фото работ. Без звонков и уточнений «ну что там».
          </p>
        </div>

        <div className="grid gap-4 md:grid-cols-5 md:gap-6">
          {/* Чат */}
          <div className="rounded-2xl border border-line bg-surface-alt p-4 md:col-span-3 md:p-6">
            <div className="mb-4 flex items-center gap-3 border-b border-line pb-4">
              <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary text-sm font-semibold text-primary-foreground">
                А
              </div>
              <div>
                <p className="text-sm font-medium text-foreground">Мастер Артём</p>
                <p className="text-xs text-muted-foreground">Гараж 24 · Химмаш</p>
              </div>
            </div>

            <div className="flex flex-col gap-3">
              {visible.map((m, i) => (
                <motion.div
                  key={m.time}
                  initial={reduced ? false : { opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.4, ease: "easeOut" }}
                  className="flex justify-start"
                >
                  <div className="max-w-[85%] rounded-2xl rounded-tl-sm bg-background px-4 py-3 shadow-sm">
                    <p className="text-sm leading-snug text-foreground">{m.text}</p>
                    {m.photo && (
                      <div className="mt-2 grid grid-cols-2 gap-1">
                        <div className="h-16 rounded-lg border border-line bg-accent md:h-20" />
                        <div className="h-16 rounded-lg border border-line bg-accent md:h-20" />
                      </div>
                    )}
                    <p className="mt-1 text-right text-[11px] text-muted-foreground">
                      {m.time}
                    </p>
                    {i === visible.length - 1 && step >= messages.length && (
                      <p className="mt-1 text-[11px] text-muted-foreground">
                        Прочитано
                      </p>
                    )}
                  </div>
                </motion.div>
              ))}
            </div>

            <div className="mt-4 flex items-center gap-2 rounded-full border border-line bg-background px-4 py-2">
              <span className="text-sm text-muted-foreground">Сообщение</span>
              <span className="ml-auto text-muted-foreground">→</span>
            </div>
          </div>

          {/* Этапы */}
          <div className="rounded-2xl border border-line bg-background p-4 md:col-span-2 md:p-6">
            <p className="mb-4 text-sm font-medium text-foreground">
              Этап ремонта в приложении
            </p>
            <ol className="flex flex-col gap-0">
              {stages.map((s, i) => {
                const done = i < activeStage;
                const current = i === activeStage && step < messages.length + 1;
                return (
                  <li key={s} className="flex items-start gap-3">
                    <div className="flex flex-col items-center">
                      <motion.div
                        initial={false}
                        animate={{
                          scale: current ? [1, 1.15, 1] : 1,
                        }}
                        transition={{ repeat: current ? Infinity : 0, duration: 1.4 }}
                        className={`flex h-5 w-5 items-center justify-center rounded-full border text-[10px] font-semibold ${
                          done || current
                            ? "border-primary bg-primary text-primary-foreground"
                            : "border-line bg-background text-muted-foreground"
                        }`}
                      >
                        {done ? "✓" : i + 1}
                      </motion.div>
                      {i < stages.length - 1 && (
                        <div
                          className={`h-8 w-px ${done ? "bg-primary" : "bg-line"}`}
                        />
                      )}
                    </div>
                    <span
                      className={`pt-0.5 text-sm ${
                        done || current
                          ? "text-foreground"
                          : "text-muted-foreground"
                      }`}
                    >
                      {s}
                      {current && (
                        <span className="ml-2 text-xs text-accent-text">
                          сейчас
                        </span>
                      )}
                    </span>
                  </li>
                );
              })}
            </ol>
            <p className="mt-5 border-t border-line pt-4 text-xs leading-relaxed text-muted-foreground">
              Гарантия 12 месяцев на работы, 6 месяцев на запчасти. Фиксируем
              цену до начала работ.
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}

