import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export default function MasterChat() {
  const reduce = useReducedMotion();

  const steps = [
    { label: "Приняли авто", time: "08:12", done: true },
    { label: "Диагностика", time: "09:40", done: true },
    { label: "Согласовали цену", time: "10:05", done: true },
    { label: "Ремонт", time: "11:30", done: true },
    { label: "Контроль качества", time: "14:20", done: false },
    { label: "Выдача", time: "—", done: false },
  ];

  return (
    <section className="border-t border-line bg-background px-5 py-16 sm:px-8">
      <div className="mx-auto grid max-w-5xl gap-10 lg:grid-cols-[1fr_1.1fr] lg:items-center">
        <div>
          <p className="text-sm font-medium text-accent-text">Статус ремонта</p>
          <h2 className="mt-3 text-3xl font-semibold leading-tight tracking-tight text-foreground sm:text-4xl">
            Видно этап без звонков
          </h2>
          <p className="mt-4 text-base leading-relaxed text-muted-foreground">
            Мастер пишет в Telegram по ходу работ: что сделано, что дальше и
            сколько это стоит. Фото узла приходит до того, как вы спросите.
          </p>
          <div className="mt-6 flex items-center gap-3 text-sm text-muted-foreground">
            <span className="inline-flex h-2 w-2 rounded-full bg-primary" />
            Мастер на связи с 8:00 до 23:00
          </div>
        </div>

        <LazyMotion features={domAnimation}>
          <div className="rounded-2xl border border-line bg-surface-alt p-4 sm:p-5">
            <div className="mb-4 flex items-center justify-between border-b border-line pb-3">
              <div className="flex items-center gap-2">
                <div className="flex h-8 w-8 items-center justify-center rounded-full bg-accent text-sm font-semibold text-accent-ink">
                  М
                </div>
                <div>
                  <p className="text-sm font-medium text-foreground">Мастер Дмитрий</p>
                  <p className="text-xs text-muted-foreground">Гараж 24 · Химмаш</p>
                </div>
              </div>
              <span className="text-xs text-muted-foreground">сегодня</span>
            </div>

            <div className="space-y-3">
              {steps.map((s, i) => (
                <div
                  key={s.label}
