import { useEffect, useState } from 'react';
import { motion, useReducedMotion } from 'motion/react';

const ROAST_LOG = [
  { time: '09:47', line: 'Эфиопия Гуджи, 12 кг, профиль фильтра' },
  { time: '11:20', line: 'Колумбия Уила, 15 кг, эспрессо-профиль' },
  { time: '14:03', line: 'Бразилия Серрадо, 18 кг, база для смеси' },
];

export default function ZernoRoastClock() {
  const reduced = useReducedMotion();
  const [index, setIndex] = useState(0);

  useEffect(() => {
    if (reduced) return;
    const id = setInterval(() => setIndex((i) => (i + 1) % ROAST_LOG.length), 3600);
    return () => clearInterval(id);
  }, [reduced]);

  const entry = ROAST_LOG[index];

  return (
    <section className="relative overflow-hidden bg-background py-14 sm:py-20">
      <div className="mx-auto max-w-5xl px-5">
        <p className="font-mono text-sm tracking-widest text-foreground/60">
          цех работает каждую неделю
        </p>

        <div className="relative mt-6">
          <div className="relative aspect-[16/9] overflow-hidden rounded-xl bg-surface-alt sm:aspect-[21/9]">
            <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_30%_40%,var(--tw-shadow-color,rgba(0,0,0,0.45)),transparent_70%)]" />

            <div className="absolute inset-x-0 bottom-0 border-t border-line/40 bg-scrim/70 px-5 pb-6 pt-4 sm:px-10 sm:pb-8">
              <div className="flex flex-wrap items-end justify-between gap-x-6 gap-y-3">
                <motion.p
                  key={`t-${entry.time}`}
                  initial={reduced ? false : { y: 60, opacity: 0 }}
                  animate={{ y: 0, opacity: 1 }}
                  transition={{ duration: 0.9, ease: [0.16, 1, 0.3, 1] }}
                  className="font-mono text-5xl font-semibold leading-none tracking-tight text-scrim-foreground sm:text-7xl"
                >
                  {entry.time}
                </motion.p>
                <motion.p
                  key={`l-${entry.time}`}
                  initial={reduced ? false : { opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: 0.55, duration: 0.7 }}
                  className="max-w-xs text-sm leading-snug text-scrim-foreground/85 sm:text-base"
                >
                  {entry.line}
                </motion.p>
              </div>
            </div>
          </div>

          <p className="mt-4 text-sm text-foreground/70 sm:text-base">
            Время выхода партии из барабана. Эта же дата стоит на пачке,
            которую вы забираете домой: 250 г от 650 ₽.
          </p>
        </div>

        <ul className="mt-8 divide-y divide-line">
          <li className="flex items-baseline justify-between py-3">
            <span>Сегодня, последняя партия</span>
            <span className="font-mono text-foreground">{entry.time}</span>
          </li>
          <li className="flex items-baseline justify-between py-3">
            <span>Сортов в активной ротации</span>
            <span className="font-mono text-foreground">6</span>
          </li>
